TEMPLATES = {'login.html': '<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Aru · Entrar</title><link rel="stylesheet" href="/assets/panel.css">\n<body><main class="login"><span class="eyebrow">POUSADA ARUANÃ</span><h1>Atendimento com a Aru</h1><p>Acesso exclusivo da equipe · ambiente de teste</p>\n<form method="post"><input type="hidden" name="csrf" value="{{ csrf }}"><label>Atendente<input name="operator" required autocomplete="username"></label><label>Senha<input name="password" type="password" required autocomplete="current-password"></label><button>ENTRAR</button></form>{% if error %}<p role="alert">{{ error }}</p>{% endif %}</main></body></html>\n', 'panel.html': '<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf }}"><meta name="operator" content="{{ operator }}"><title>Aru · Atendimento</title><link rel="stylesheet" href="/assets/panel.css"><script src="/assets/panel.js" defer></script>\n<body><header><div><span class="eyebrow">POUSADA ARUANÃ · TESTE</span><h1>Aru, junto com a equipe</h1></div><div>{{ operator }} <button id="logout" class="secondary">SAIR</button></div></header>\n<p id="notice" role="status">Carregando conversas…</p><main class="workspace"><aside><h2>Conversas</h2><p>As solicitações aguardando a equipe aparecem aqui.</p><div id="conversations"></div></aside><section><h2 id="title">Selecione uma conversa</h2><p id="mode"></p><div class="actions"><button id="claim" disabled>ASSUMIR</button><button id="release" class="secondary" disabled>DEVOLVER PARA ARU</button></div><details><summary>Dados da estadia e disponibilidade</summary><pre id="facts"></pre><p>Omnibees · propriedade 18272. Consulta automática ainda não conectada. Confira valores, disponibilidade e regras antes de informar ao hóspede.</p></details><div id="messages" aria-live="polite"></div><form id="compose"><label for="message">Mensagem da equipe</label><textarea id="message" maxlength="3500" rows="3" disabled placeholder="Assuma a conversa para responder."></textarea><button id="send" disabled>ENVIAR PELO WHATSAPP</button></form></section></main></body></html>\n'}
ASSETS = {'panel.css': ':root{font-family:system-ui,sans-serif;color:#173c3b;background:#f4f6f3;line-height:1.55}*{box-sizing:border-box}body{margin:0}header{background:#153f3c;color:white;padding:24px 5%;display:flex;justify-content:space-between;align-items:center;gap:20px}h1{font-size:26px;margin:4px 0}h2{font-size:21px}p{color:#536b68}.eyebrow{font-size:11px;letter-spacing:2px}button{border:0;border-radius:7px;background:#14685c;color:#fff;padding:12px 17px;font-weight:650;cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}.secondary{background:#e4ece8;color:#173c3b}input,textarea{font:inherit;width:100%;border:1px solid #acbfba;border-radius:7px;padding:12px;background:white;color:#183d38}label{display:block;margin:15px 0 6px}#notice{padding:12px 5%;margin:0;background:#e8efe9;min-height:48px}.workspace{max-width:1250px;margin:26px auto;display:grid;grid-template-columns:290px 1fr;gap:24px;padding:0 20px}aside,section{background:white;padding:22px;border:1px solid #d9e2dd;border-radius:12px}.actions{display:flex;gap:10px;flex-wrap:wrap}details{margin:20px 0;padding:14px;background:#f2f5f1;border-radius:8px}summary{cursor:pointer}pre{white-space:pre-wrap;font:inherit;font-size:14px}#messages{height:370px;overflow:auto;padding:12px;background:#f6f8f5;border-radius:8px}.bubble{white-space:pre-wrap;border:1px solid #d6e3de;background:white;border-radius:10px;padding:10px 14px;margin:10px 0;max-width:90%;overflow-wrap:anywhere}.bubble.assistant,.bubble.human{margin-left:auto;background:#e1f0e8}.meta{font-size:11px;color:#57766d;margin-bottom:4px}.conversation{width:100%;text-align:left;margin:6px 0;background:#edf4ef;color:#16473e}.conversation.active{outline:2px solid #14685c}.login{max-width:430px;margin:12vh auto;padding:30px;background:white;border:1px solid #d9e2dd;border-radius:14px}.login button{width:100%;margin-top:20px}#compose button{margin-top:8px}@media(max-width:760px){header{align-items:start;flex-direction:column}.workspace{grid-template-columns:1fr}.login{margin:8vh 18px}#messages{height:320px}}\n', 'panel.js': '\'use strict\';\nconst $ = id => document.getElementById(id);\nconst csrf = document.querySelector(\'meta[name="csrf-token"]\').content;\nconst operator = document.querySelector(\'meta[name="operator"]\').content;\nconst labels = {aru:\'Aru atendendo\',waiting:\'Aguardando equipe\',human:\'Atendimento humano\'};\nconst reasons = {availability:\'Conferir disponibilidade\',payment:\'Pagamento\',complaint:\'Reclamação\',exception:\'Exceção ou alteração\',human:\'Pedido de atendente\',information:\'Informação da pousada\',ai_unavailable:\'Atendimento automático indisponível\',send_failed:\'Falha de envio\',window_closed:\'Aguardando nova mensagem do hóspede\'};\nconst states = {queued:\'Na fila\',processing:\'Processando\',processed:\'Processada\',human:\'Para a equipe\',accepted:\'Aceita pela Meta\',sent:\'Enviada\',delivered:\'Entregue\',read:\'Lida\',failed:\'Falha\',uncertain:\'Envio não confirmado\'};\nlet selected = null, busy = false, current = null;\nasync function api(path, data) {\n  const response = await fetch(path, data === undefined ? {cache:\'no-store\'} : {\n    method:\'POST\', headers:{\'Content-Type\':\'application/json\',\'X-CSRF-Token\':csrf}, body:JSON.stringify(data)});\n  if(response.status === 401){location.href=\'/login\';throw new Error(\'Entre novamente.\');}\n  const value = await response.json().catch(()=>({error:\'Não foi possível concluir. Atualize a página.\'}));\n  if(!response.ok) throw new Error(value.error || \'Falha na operação.\');\n  return value;\n}\nfunction status(text){$(\'notice\').textContent=text;}\nfunction controls(){\n  const mine = current && current.mode===\'human\' && current.owner===operator;\n  $(\'claim\').disabled=busy || !current || !!(current.owner && current.owner!==operator) || mine;\n  $(\'release\').disabled=busy || !mine;\n  $(\'send\').disabled=busy || !mine;\n  $(\'message\').disabled=busy || !mine;\n}\nasync function refresh(){\n  const list=await api(\'/api/conversations\');\n  $(\'conversations\').replaceChildren();\n  for(const item of list){\n    const button=document.createElement(\'button\');button.className=\'conversation\'+(selected===item.sender?\' active\':\'\');\n    button.textContent=\'+\'+item.sender+\' · \'+labels[item.mode];\n    button.onclick=()=>{selected=item.sender;refresh().catch(e=>status(e.message));};\n    $(\'conversations\').append(button);\n  }\n  if(!selected){status(list.length?\'Escolha uma conversa para acompanhar.\':\'Aguardando a primeira mensagem do testador.\');return;}\n  const data=await api(\'/api/conversations/\'+encodeURIComponent(selected));\n  current=data.conversation;\n  $(\'title\').textContent=\'+\'+selected;\n  $(\'mode\').textContent=labels[current.mode]+(current.owner?\' · \'+current.owner:\'\')+(current.reason?\' · \'+(reasons[current.reason]||\'Conferir solicitação\'):\'\');\n  const names={checkin:\'Entrada\',checkout:\'Saída\',adults:\'Adultos\',children:\'Crianças\',ages:\'Idades\',pets:\'Pets\',pet_details:\'Sobre os pets\'};\n  $(\'facts\').textContent=Object.entries(names).map(([k,v])=>{const value=current.facts[k];return v+\': \'+(value===null || value===undefined?\'Não informado\':typeof value===\'boolean\'?(value?\'Sim\':\'Não\'):Array.isArray(value)?(value.length?value.join(\', \'):\'Nenhuma\'):String(value));}).join(\'\\n\');\n  const nearBottom=$(\'messages\').scrollHeight-$(\'messages\').scrollTop-$(\'messages\').clientHeight<80;\n  $(\'messages\').replaceChildren();\n  for(const message of data.messages){\n    const bubble=document.createElement(\'div\');bubble.className=\'bubble \'+message.role;\n    const meta=document.createElement(\'div\');meta.className=\'meta\';\n    meta.textContent=({user:\'Hóspede\',assistant:\'Aru\',human:\'Equipe\'}[message.role]||message.role)+\' · \'+(states[message.state]||message.state)+(message.error?\' · \'+message.error:\'\');\n    const body=document.createElement(\'div\');body.textContent=message.body;\n    bubble.append(meta,body);$(\'messages\').append(bubble);\n  }\n  if(nearBottom)$(\'messages\').scrollTop=$(\'messages\').scrollHeight;\n  controls();\n}\nasync function act(action,data={}){\n  if(busy || !selected)return;\n  busy=true;controls();\n  try{\n    const result=await api(\'/api/conversations/\'+encodeURIComponent(selected)+\'/\'+action,data);\n    if(action===\'enviar\')$(\'message\').value=\'\';\n    status(result.warning || ({assumir:\'Você assumiu. A Aru está pausada.\',devolver:\'Aru reativada. As próximas mensagens serão atendidas por ela.\',enviar:\'Envio aceito. Acompanhe a confirmação de entrega no histórico.\'}[action]));\n    await refresh();\n  }catch(e){status(e.message);}finally{busy=false;controls();}\n}\n$(\'claim\').onclick=()=>act(\'assumir\');\n$(\'release\').onclick=()=>act(\'devolver\');\n$(\'compose\').onsubmit=e=>{e.preventDefault();if($(\'message\').value.trim())act(\'enviar\',{text:$(\'message\').value,nonce:crypto.randomUUID()});};\n$(\'logout\').onclick=async()=>{try{await api(\'/api/logout\',{});location.href=\'/login\';}catch(e){status(e.message);}};\nrefresh().catch(e=>status(e.message));\nsetInterval(()=>{if(!busy)refresh().catch(e=>status(e.message));},5000);\n'}
